export class APIError extends Error {
  constructor(public status: number, message: string, public body?: unknown) { super(message); }
}

async function parseError(response: Response) {
  const raw = await response.text();
  try { return JSON.parse(raw); } catch { return raw; }
}

export async function apiFetch<T>(path: string, init: RequestInit = {}, parser?: { parse(value: unknown): T }): Promise<T> {
  const response = await fetch(path, {
    ...init,
    headers: { "content-type": "application/json", ...(init.headers || {}) },
    cache: "no-store"
  });
  if (response.status === 401 && typeof window !== "undefined") {
    window.location.assign("/login?error=session_expired");
    throw new APIError(401, "Session expired");
  }
  if (!response.ok) {
    const body = await parseError(response);
    throw new APIError(response.status, typeof body === "string" ? body : JSON.stringify(body), body);
  }
  if (response.status === 204) return undefined as T;
  const value = await response.json();
  return parser ? parser.parse(value) : value as T;
}

const mutationFetch = (path: string, init: RequestInit = {}) => apiFetch<MutationResponse>(path, init, mutationResponseSchema);

